const BackgroundJaw: React.FC<{ width: number }> = ({ width }) => {
  return (
    <div style={{
      position: "absolute",
      top: "20%",
      left: "50%",
      transform: "translateX(-50%)",
      width: width * 0.9,
      height: "400px",
      display: "flex",
      justifyContent: "center",
      alignItems: "center",
      gap: "15px",
      opacity: 0.15,
      filter: "blur(8px)",
      zIndex: 2,
    }}>
      {Array.from({length: 9}).map((_, i) => {
        const dist = Math.abs(4 - i);
        const h = 180 - dist * 25;
        const translateY = dist * 30;
        const rotate = (i - 4) * 8;
        return (
          <div key={i} style={{
            width: "75px",
            height: `${Math.max(50, h)}px`,
            backgroundColor: "#fff",
            borderRadius: "35px 35px 70px 70px",
            transform: `translateY(-${translateY}px) rotate(${rotate}deg)`,
            boxShadow: "0 0 60px #fff"
          }}/>
        );
      })}
    </div>
  );
};

const OrbitalRings: React.FC<FrameProps> = ({ width, height, frame }) => {
  const cx = width / 2;
  const cy = height / 2;
  
  const rings = [
    { rx: width * 0.4, ry: height * 0.1, rotate: -20, duration: 150, delay: 0 },
    { rx: width * 0.45, ry: height * 0.15, rotate: 15, duration: 200, delay: 50 },
    { rx: width * 0.5, ry: height * 0.12, rotate: -5, duration: 180, delay: 100 },
  ];
  
  return (
    <svg width={width} height={height} style={{ position: "absolute", pointerEvents: "none", zIndex: 3 }}>
      <defs>
        <linearGradient id="ringGlow" x1="0%" y1="0%" x2="100%" y2="0%">
          <stop offset="0%" stopColor="transparent" />
          <stop offset="50%" stopColor="#fff" stopOpacity="0.8" />
          <stop offset="100%" stopColor="transparent" />
        </linearGradient>
      </defs>
      {rings.map((r, i) => {
        const p = Math.PI * (3 * (r.rx + r.ry) - Math.sqrt((3 * r.rx + r.ry) * (r.rx + 3 * r.ry)));
        const progress = ((frame + r.delay) % r.duration) / r.duration;
        const dashoffset = p * (1 - progress);
        
        return (
          <g key={i}>
            <ellipse
              cx={cx} cy={cy} rx={r.rx} ry={r.ry}
              fill="none" stroke="rgba(255,255,255,0.15)" strokeWidth="1"
              style={{ transformOrigin: `${cx}px ${cy}px`, transform: `rotate(${r.rotate}deg)` }}
            />
            <ellipse
              cx={cx} cy={cy} rx={r.rx} ry={r.ry}
              fill="none" stroke="url(#ringGlow)" strokeWidth="3"
              strokeDasharray={`${p * 0.2} ${p * 0.8}`}
              strokeDashoffset={dashoffset}
              style={{ transformOrigin: `${cx}px ${cy}px`, transform: `rotate(${r.rotate}deg)` }}
              filter="drop-shadow(0 0 8px rgba(255,255,255,0.8))"
            />
          </g>
        );
      })}
    </svg>
  );
};

const Clocks: React.FC<FrameProps> = ({ frame, width, height }) => {
  const items = [
    { x: 0.15, y: 0.45, scale: 0.8, delay: 0 },
    { x: 0.85, y: 0.55, scale: 1.1, delay: 30 },
    { x: 0.2, y: 0.75, scale: 0.6, delay: 60 },
    { x: 0.8, y: 0.35, scale: 0.7, delay: 15 },
  ];
  
  return (
    <>
      {items.map((item, i) => {
        const floatY = Math.sin((frame + item.delay) / 30) * 30;
        const rotate = (frame * 0.3) + item.delay;
        const handRotate = frame * 2;
        
        return (
          <div key={i} style={{
            position: "absolute",
            left: width * item.x - 50,
            top: height * item.y + floatY - 50,
            transform: `scale(${item.scale}) rotate(${rotate}deg)`,
            opacity: 0.35,
            width: 100, height: 100,
            zIndex: 4,
            transition: "none"
          }}>
            <svg viewBox="0 0 100 100" width="100%" height="100%" filter="drop-shadow(0 0 5px rgba(255,255,255,0.5))">
              <circle cx="50" cy="50" r="46" fill="none" stroke="#fff" strokeWidth="2" />
              <circle cx="50" cy="50" r="40" fill="none" stroke="rgba(255,255,255,0.5)" strokeWidth="1" strokeDasharray="4 6"/>
              <g style={{ transformOrigin: "50px 50px", transform: `rotate(${handRotate}deg)` }}>
                <line x1="50" y1="50" x2="50" y2="25" stroke="#fff" strokeWidth="3" strokeLinecap="round" />
              </g>
              <g style={{ transformOrigin: "50px 50px", transform: `rotate(${handRotate / 12}deg)` }}>
                <line x1="50" y1="50" x2="65" y2="50" stroke="#fff" strokeWidth="2" strokeLinecap="round" />
              </g>
              <circle cx="50" cy="50" r="3" fill="#fff" />
            </svg>
          </div>
        );
      })}
    </>
  );
};

