const LightRays: React.FC<{ frame: number }> = ({ frame }) => {
  return (
    <div style={{
      position: "absolute",
      top: "-10%",
      left: "-10%",
      width: "120%",
      height: "120%",
      pointerEvents: "none",
      zIndex: 8,
      overflow: "hidden"
    }}>
      {Array.from({length: 6}).map((_, i) => {
        const opacity = 0.05 + Math.sin(frame / 15 + i) * 0.03;
        const rot = -25 + (i * 5);
        return (
          <div key={i} style={{
            position: "absolute",
            top: "-20%",
            left: `${10 + i * 15}%`,
            width: `${80 + (i%3)*40}px`,
            height: "150%",
            background: "linear-gradient(to bottom, rgba(255,255,255,0.6) 0%, transparent 80%)",
            transformOrigin: "top center",
            transform: `rotate(${rot}deg)`,
            opacity: opacity,
            filter: "blur(25px)",
            transition: "none"
          }} />
        );
      })}
    </div>
  );
};

const Sparks: React.FC<FrameProps> = ({ width, height, frame }) => {
  const cx = width / 2;
  const cy = height / 2 - 50;
  
  const targets = [
    { x: cx - 180, y: cy - 120 },
    { x: cx - 100, y: cy - 150 },
    { x: cx, y: cy - 180 },
    { x: cx + 100, y: cy - 150 },
    { x: cx + 180, y: cy - 120 },
  ];
  
  return (
    <svg width={width} height={height} style={{ position: "absolute", pointerEvents: "none", zIndex: 6 }}>
      {targets.map((t, i) => {
        const dx = t.x - cx;
        const dy = t.y - cy;
        
        const progress = ((frame * 2 + i * 20) % 100) / 100;
        
        const sx = cx + dx * progress;
        const sy = cy + dy * progress;
        const opacity = Math.sin(progress * Math.PI); 
        
        return (
          <g key={i}>
            <line x1={cx} y1={cy} x2={t.x} y2={t.y} stroke="rgba(255,255,255,0.15)" strokeWidth="1" />
            <circle cx={sx} cy={sy} r="2" fill="#fff" opacity={opacity} filter="drop-shadow(0 0 5px #fff)" />
          </g>
        );
      })}
    </svg>
  );
};

const Particles: React.FC<FrameProps & { count: number }> = ({ frame, width, height, count }) => {
  return (
    <>
      {Array.from({ length: count }).map((_, i) => {
        const randX = ((i * 13.5) % 100) / 100;
        const randY = ((i * 27.1) % 100) / 100;
        const randSpeed = 0.5 + ((i * 3.3) % 2);
        const randSize = 2 + ((i * 7.7) % 5);
        
        const startY = height * randY;
        const wrappedY = height - ((frame * randSpeed + startY) % height);
        const currentX = width * randX + Math.sin(frame / 30 + i) * 30;
        const opacity = 0.1 + Math.sin(frame / 15 + i) * 0.4;

        return (
          <div key={i} style={{
            position: "absolute",
            left: currentX,
            top: wrappedY,
            width: randSize,
            height: randSize,
            backgroundColor: "#fff",
            borderRadius: "50%",
            opacity: opacity,
            boxShadow: "0 0 8px #fff",
            zIndex: 7,
            transition: "none"
          }} />
        );
      })}
    </>
  );
};


const DentalImplant: React.FC<DentalImplantProps> = ({
  backgroundColor = "#040b1a",
  transparentBackground = false,
  durationInSeconds = 30,
  titleLine1 = "LONG TERM",
  titleLine1FontFamily = "Playfair Display",
  titleLine2 = "FIX SOLUTION",
  titleLine2FontFamily = "Playfair Display",
  glowColor = "#fdf6e3",
  particleCount = 40,
  showFloatingClocks = true,
  showFloatingCoins = true,
}) => {
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  const getFontFamily = (fontName: string) => {
    switch (fontName) {
      case "Inter": return interFamily;
      case "Space Grotesk": return spaceFamily;
      case "Playfair Display": default: return playfairFamily;
    }
  };

  const initialY = spring({
    frame,
    fps,
    config: { damping: 12, mass: 1 }
  });
  
  const yPos = interpolate(initialY, [0, 1], [300, 0]);
  const implantOpacity = interpolate(initialY, [0, 1], [0, 1]);
  const floatY = Math.sin(frame / 30) * 15;
  const rotate = Math.sin(frame / 45) * 4;

  const titleScale1 = spring({ frame: frame - 15, fps, config: { damping: 14, mass: 0.8 } });
  const titleScale2 = spring({ frame: frame - 25, fps, config: { damping: 14, mass: 0.8 } });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {!transparentBackground && (
        <div style={{
          position: "absolute", width: "100%", height: "100%",
          background: `radial-gradient(circle at 40% 20%, rgba(255,255,255,0.1) 0%, transparent 50%), linear-gradient(135deg, rgba(17,32,59,0.5) 0%, transparent 100%)`
        }} />
      )}

      <BackgroundJaw width={width} />
      <OrbitalRings frame={frame} width={width} height={height} />
      
      {showFloatingClocks && <Clocks frame={frame} width={width} height={height} />}
      {showFloatingCoins && <Coins frame={frame} width={width} height={height} />}
      
      <div style={{
        position: "absolute",
        top: height * 0.45 - 175,
        left: width * 0.5 - 100,
        transform: `translateY(${yPos + floatY}px) rotate(${rotate}deg) scale(1.4)`,
        opacity: implantOpacity,
        filter: "drop-shadow(0 0 30px rgba(255,255,255,0.3))",
        zIndex: 5,
        transition: "none"
      }}>
        <ImplantSVG />
      </div>

      <Sparks frame={frame} width={width} height={height} />
      <Particles frame={frame} width={width} height={height} count={particleCount} />
      <LightRays frame={frame} />

      <div style={{
        position: "absolute",
        bottom: "12%",
        width: "100%",
        textAlign: "center",
        display: "flex",
        flexDirection: "column",
        gap: "15px",
        color: "#fdf6e3",
        zIndex: 10
      }}>
        <div style={{ 
          fontSize: "85px", 
          fontFamily: getFontFamily(titleLine1FontFamily),
          transform: `scale(${titleScale1})`, 
          opacity: Math.min(1, titleScale1 * 1.5),
          textShadow: `0 0 15px ${glowColor}, 0 0 30px ${glowColor}`,
          lineHeight: 1.1,
          transition: "none"
        }}>
          {titleLine1}
        </div>
        <div style={{ 
          fontSize: "95px", 
          fontFamily: getFontFamily(titleLine2FontFamily),
          transform: `scale(${titleScale2})`, 
          opacity: Math.min(1, titleScale2 * 1.5),
          textShadow: `0 0 15px ${glowColor}, 0 0 30px ${glowColor}`,
          lineHeight: 1.1,
          transition: "none"
        }}>
          {titleLine2}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default DentalImplant;